"""Detailed explanations with diagrams: HLD questions, part 4."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, ER, TABLE, CALC, BARS, CODE, UML, STATE

X("adclick-hld",
  P("""**What the system does.** Counts ad clicks per ad per minute so advertisers see near-real-time dashboards and are **billed correctly**. Money is involved, so counts must be exact and auditable: no lost clicks, no double counting, clicks that arrive late still land in the right minute, and bots are filtered."""),
  AN("A toll booth system: every car passing is photographed with a unique ticket number (click id) and a timestamp. Booths send photos to a central office that counts per minute by the time on the photo, not the time it arrived. Every night auditors recount from the raw photos before invoices go out."),
  CALC("Sizing", [("Clicks per second", "1e9 / 86400", "/s"), ("Raw log per day", "1e9 * 100", "B"), ("Aggregate rows per day (2 M active ads × 1,440 minutes)", "2e6 * 1440", "")]),
  SEQ("One click, counted exactly once", ["Browser", "Ad server", "Kafka", "Flink job", "OLAP store"],
      [["Browser", "Ad server", "GET /click?ad=7&cid=uuid", "", "The redirect endpoint logs the click with a unique click id and the event time, then redirects to the advertiser."],
       ["Ad server", "Kafka", "ClickEvent{cid, ad, ts, ip}", "a"], ["Flink job", "Kafka", "consume (keyed by ad id)"],
       ["Flink job", "Flink job", "dedupe cid; filter bots; add to window [10:01, 10:02) by **event time**", "", "Watermarks say 'probably no more events before 10:02'; allowed lateness keeps the window open a little longer for stragglers."],
       ["Flink job", "OLAP store", "upsert (ad 7, 10:01) = 1,532", "", "Checkpoints + Kafka transactions + an idempotent upsert sink give exactly-once results even after crashes."],
       NOTE(["Ad server", "OLAP store"], "nightly: batch job recounts from the raw S3 log and reconciles before billing")]),
  TABLE("Event time vs processing time", ["Click happened", "Arrived (phone was offline)", "Counted in minute (processing time)", "Counted in minute (event time ✔)"],
        [["10:01:30", "10:01:31", "10:01", "10:01"], ["10:01:50", "10:04:10", "10:04 ✘", "10:01 (late, within allowed lateness)"]]),
  TABLE("Correctness toolkit", ["Problem", "Solution"], [["duplicates (retries)", "unique click id, dedupe in state with TTL"], ["crash mid-stream", "Flink checkpoints + exactly-once sinks"], ["late events", "event time + watermarks + allowed lateness"],
        ["click fraud", "rules + ML on IP, device, rate before counting"], ["bugs in the stream job", "raw log kept; replay or batch recount (lambda architecture)"]]))

X("jobscheduler-hld",
  P("""**What the system does.** Runs millions of scheduled jobs ('every day at 02:00', 'in 30 minutes') reliably across many machines: each scheduled run must be **triggered exactly once**, executed even if a worker dies, and the system must survive the **midnight spike** when huge numbers of jobs are due at the same second."""),
  AN("A railway timetable office: clerks each own a few pages of the timetable (partitions). A minute before departures they write a ticket for each due train into a ledger that refuses duplicate (train, time) tickets, then hand tickets to drivers (workers). A driver who falls asleep loses the ticket when their lease expires and another driver takes it."),
  CALC("Sizing", [("Executions per second (average)", "10e6 / 86400", "/s"), ("Midnight burst", "100e3", "/s", "spread with jitter where the job allows it"), ("Run-history rows per year", "10e6 * 365", "")]),
  SEQ("Triggering and running a job", ["Scheduler shard", "Jobs DB", "Run table", "Queue", "Worker"],
      [["Scheduler shard", "Jobs DB", "jobs in my partitions with next_run_at ≤ now + 10 s", "", "Shards own time-bucket partitions through leases (etcd/ZooKeeper), so only one shard scans each partition."],
       ["Scheduler shard", "Run table", "INSERT run (job 42, scheduled_for 02:00) — UNIQUE", "", "If a failover makes two shards try, the unique constraint lets only one insert succeed: exactly-once **triggering**."],
       ["Scheduler shard", "Jobs DB", "next_run_at = next cron time"], ["Scheduler shard", "Queue", "enqueue run id", "a"],
       ["Worker", "Queue", "take run; set lease_until = now + 60 s"], ["Worker", "Worker", "execute (idempotent) and heartbeat the lease", "", "If the worker dies, the lease expires and the run is re-queued: at-least-once **execution**, so jobs must be idempotent."],
       ["Worker", "Run table", "status = SUCCEEDED"]]),
  ER("Tables", [("jobs", "SQL, partitioned by next_run_at bucket", [("job_id", "bigint", "PK"), ("tenant_id", "", "IDX"), ("cron", "text", ""), ("next_run_at", "timestamptz", "IDX"), ("payload", "json", ""), ("max_retries", "int", "")], ""),
                ("runs", "SQL", [("job_id", "bigint", "PK"), ("scheduled_for", "timestamptz", "PK"), ("status", "", ""), ("attempt", "int", ""), ("worker", "", ""), ("lease_until", "timestamptz", "IDX")], "The (job_id, scheduled_for) key is what prevents double triggering.")]),
  KEY("Say clearly: **triggering** is exactly-once (unique constraint), **execution** is at-least-once (leases + retries), so the job itself must be idempotent. That's the honest guarantee every real scheduler gives.", "The key sentence"))

X("email-hld",
  P("""**What the system does.** Receive email from the whole internet over SMTP, filter spam and viruses, store it per user, let users read and search years of mail instantly, and send mail out reliably. Scale: billions of users and hundreds of thousands of incoming emails per second. Everything is **sharded by user**, which keeps each mailbox's data and search index small."""),
  AN("A giant sorting office: incoming sacks are checked at the gate (SPF/DKIM, spam scanner), each letter is filed into the recipient's personal cabinet (shard by user) with an index card in that person's own card box (per-user search index). Photocopies of the same brochure sent to millions are stored once (attachment dedup)."),
  CALC("Sizing", [("Incoming emails per second", "1.5e9 * 50 / 86400", "/s"), ("Raw bytes per day (50 KB average)", "1.5e9 * 50 * 50e3", "B"), ("Per user per year (50/day × 50 KB)", "50 * 365 * 50e3", "B", "before compression and dedup")]),
  SEQ("An email arrives", ["Sender's server", "SMTP gateway", "Spam/virus filter", "Mailbox service", "Blob store", "Search indexer", "Recipient app"],
      [["Sender's server", "SMTP gateway", "SMTP: MAIL FROM / RCPT TO / DATA"], ["SMTP gateway", "SMTP gateway", "SPF, DKIM, DMARC checks", "", "Is the sending server allowed to send for that domain, and is the signature valid?"],
       ["SMTP gateway", "Spam/virus filter", "message"], ["Spam/virus filter", "Mailbox service", "verdict: inbox (score 0.03)", "", "Reputation of sender IP/domain + ML on content + users' 'report spam' feedback."],
       ["Mailbox service", "Blob store", "body + attachments (dedup by hash)"], ["Mailbox service", "Mailbox service", "metadata row (user, thread, labels) in Bigtable"],
       ["Mailbox service", "Search indexer", "index for this user", "a"], ["Mailbox service", "Recipient app", "push: new mail", "a"]]),
  TABLE("Why shard by user", ["Operation", "Touches"], [["open inbox", "one user's rows (row key user_id + thread_id)"], ["search 'invoice 2024'", "one user's small index, not a global one"], ["storage growth", "add shards; users spread evenly"]]),
  TABLE("Outgoing mail", ["Step", "Detail"], [["queue", "persisted outbound queue per destination domain"], ["sign", "DKIM signature with our domain key"], ["deliver", "MX lookup, SMTP to the recipient's server"],
        ["retry", "temporary failures retried with backoff for up to several days"], ["bounces", "permanent failure → bounce message to the sender"]]))

X("s3-hld",
  P("""**What the system does.** Stores objects (any bytes, from 1 KB to terabytes) under `bucket/key`, with **eleven nines of durability** and high availability, at 100 PB scale. Split the problem in two: a **metadata service** that knows where every object's pieces live, and **data nodes** that store immutable, checksummed chunks spread across failure zones."""),
  AN("A cloakroom for valuables across three buildings: the front desk book (metadata) records which shelves in which buildings hold the pieces of your item; the shelves (data nodes) only store numbered boxes. Losing a whole building still leaves enough pieces elsewhere to rebuild your item."),
  CALC("Sizing", [("Objects stored (1 MB average)", "o = 100e15 / 1e6", ""), ("Metadata (≈ 500 B per object)", "o * 500", "B", "a sharded, replicated KV"),
                  ("Raw disk with 3× replication", "100e15 * 3", "B"), ("Raw disk with 6+3 erasure coding", "100e15 * 1.5", "B", "same loss tolerance, half the disks")]),
  SEQ("PUT photos/cat.jpg (10 MB)", ["Client", "API front-end", "Placement service", "Data nodes (3 AZs)", "Metadata service"],
      [["Client", "API front-end", "PUT /bucket/photos/cat.jpg (signed request)"], ["API front-end", "Placement service", "where should 9 chunks go?", "", "Picks healthy nodes with free space, spread across availability zones and racks."],
       ["API front-end", "Data nodes (3 AZs)", "stream 6 data + 3 parity chunks (erasure coding)", "", "Any 6 of the 9 chunks can rebuild the object, so up to 3 can be lost."],
       ["Data nodes (3 AZs)", "API front-end", "chunks durable (fsync) + checksums", "r"],
       ["API front-end", "Metadata service", "commit (bucket, key, version) → chunk locations, ETag", "", "Only after all chunks are durable is the metadata written: readers never see a half-written object."],
       ["API front-end", "Client", "200 OK, ETag", "r"]]),
  TABLE("Replication vs erasure coding", ["", "3× replication", "Erasure coding 6+3"], [["storage overhead", "3×", "1.5×"], ["failures tolerated", "2 copies", "3 chunks"], ["read cost", "read 1 copy", "read 6 chunks (or 1 if cached)"],
                                                                                    ["repair cost", "copy 1 object", "read 6 chunks to rebuild 1"], ["typical use", "hot, small objects", "cold/large data (most of S3)"]]),
  TABLE("Background work that keeps eleven nines", ["Job", "What it does"], [["scrubber", "re-reads chunks, verifies checksums, rebuilds corrupt ones"], ["repairer", "when a disk/node dies, rebuilds its chunks elsewhere quickly"],
        ["garbage collector", "deletes chunks of deleted/overwritten versions"], ["multipart upload", "large objects uploaded in parallel parts, committed together"]]))

X("fooddelivery-hld",
  P("""**What the system does.** Customers discover restaurants and order; the restaurant cooks; a delivery partner is dispatched to arrive **just as the food is ready**, then delivers it. It combines a marketplace search (geo + text), an order state machine, high-rate location tracking (like Uber), and **timing predictions** (prep time and travel ETA)."""),
  AN("An air-traffic controller for scooters: knowing a biryani takes 18 minutes to cook, the controller sends the nearest free rider so they arrive at minute 17, not at minute 2 (wasting the rider's time) or minute 30 (cold food)."),
  CALC("Sizing", [("Orders per second (average)", "3e6 / 86400", "/s"), ("Dinner peak", "200", "/s"), ("Partner location writes", "300e3 / 5", "/s"), ("Active orders at peak (≈ 40 min each)", "200 * 60 * 40", "")]),
  STATE("Order states", [["PLACED"], ["PAID", "CANCELLED"], ["ACCEPTED_BY_RESTAURANT"], ["PARTNER_ASSIGNED"], ["PICKED_UP"], ["DELIVERED"]],
        [["PLACED", "PAID", "payment ok"], ["PLACED", "CANCELLED", "payment failed"], ["PAID", "ACCEPTED_BY_RESTAURANT", ""], ["PAID", "CANCELLED", "restaurant rejects → refund"], ["ACCEPTED_BY_RESTAURANT", "PARTNER_ASSIGNED", "dispatch"], ["PARTNER_ASSIGNED", "PICKED_UP", ""], ["PICKED_UP", "DELIVERED", ""]]),
  SEQ("Dispatch timed to the food", ["Order service", "ETA/ML", "Dispatch", "Partner locations (Redis GEO)", "Partner"],
      [["Order service", "ETA/ML", "predict prep time (restaurant, items, current load)"], ["ETA/ML", "Order service", "18 min", "r"],
       ["Order service", "Dispatch", "dispatch at t ≈ 18 − travel time", "", "Start looking early enough that a rider arrives when food is ready."],
       ["Dispatch", "Partner locations (Redis GEO)", "GEOSEARCH free partners within 3 km of restaurant"], ["Dispatch", "Dispatch", "score: ETA to restaurant, current batch, rating", "", "A rider already carrying one order nearby may take a second (batching)."],
       ["Dispatch", "Partner", "offer (30 s to accept)"], ["Partner", "Dispatch", "accept → atomic assign (partner AVAILABLE → BUSY)", "r"]]),
  TABLE("Stores", ["Data", "Store", "Why"], [["restaurants + menus", "SQL + Elasticsearch (geo + text)", "rich search, read-heavy, cached"], ["orders", "SQL", "state machine, payments"],
        ["partner locations", "Redis GEO with TTL", "60k writes/s, only latest matters"], ["events", "Kafka", "tracking, analytics, ETA model training"]]))

X("onlinejudge-hld",
  P("""**What the system does.** Users submit code; the system compiles and runs it against hidden test cases with time and memory limits and returns a verdict (Accepted, Wrong Answer, TLE, …). The core problem is **running untrusted code safely**, and the scale problem is **contests**, where 100× normal traffic arrives in minutes."""),
  AN("An exam hall: each answer sheet (submission) is checked in a sealed room (sandbox) with a stopwatch and a fixed amount of paper (CPU/memory limits), no phones (no network). During finals you open more rooms in advance (pre-warmed workers)."),
  CALC("Sizing", [("Normal submissions", "10", "/s"), ("Contest peak", "c = 1000", "/s"), ("CPU-seconds needed per second at peak (1.5 s each)", "c * 1.5", ""), ("Worker cores at 70% utilisation", "c * 1.5 / 0.7", "")]),
  SEQ("A submission's journey", ["User", "API", "Queue (per language)", "Judge worker", "Sandbox", "Leaderboard"],
      [["User", "API", "POST /submit {problem, lang: java, code}"], ["API", "API", "store submission PENDING"], ["API", "Queue (per language)", "enqueue", "a", "Per-language queues let you scale Java workers separately from Python."],
       ["API", "User", "submission id (poll or WebSocket for result)", "r"], ["Judge worker", "Queue (per language)", "take"],
       ["Judge worker", "Sandbox", "compile + run each test (no network, cgroup CPU/mem limits, seccomp, timeout)", "", "gVisor/Firecracker microVMs or nsjail; a fresh sandbox per submission so nothing leaks between users."],
       ["Sandbox", "Judge worker", "outputs, time, memory", "r"], ["Judge worker", "Judge worker", "compare with expected output → verdict"],
       ["Judge worker", "Leaderboard", "ZADD contest:12 score user", "", "Contest score encodes solved count and penalty time in one number."]]),
  TABLE("Sandbox defences", ["Threat", "Defence"], [["infinite loop", "wall-clock and CPU timeouts"], ["fork bomb / memory hog", "cgroup pids and memory limits"], ["reading other files / the network", "read-only FS, no network namespace, seccomp syscall filter"],
        ["escaping the container", "microVM isolation (Firecracker/gVisor)"], ["cheating", "hidden tests, plagiarism detection afterwards"]]))

X("leaderboard-hld",
  P("""**What the system does.** Shows the top players and **my rank** among 25 million players in real time, with thousands of score updates per second. A database `ORDER BY score LIMIT 10` is fine for the top 10, but 'what is my rank?' would count millions of rows. A **Redis sorted set** (a skip list) answers both in O(log n)."""),
  AN("A sorted set is like a ladder where everyone stands on the rung of their score, with express elevators (skip-list levels) that let you jump many rungs at a time. Finding your position or the top 10 takes a few jumps, not walking past everyone."),
  CALC("Sizing", [("Score updates per second", "25e6 * 10 / 86400", "/s"), ("Peak", "10e3", "/s"), ("Memory for 25 M members (~100 B each in a ZSET)", "25e6 * 100", "B", "one Redis node is enough")]),
  TABLE("Redis commands and their cost", ["Question", "Command", "Cost"], [["add points", "ZINCRBY lb:2026-11 50 user:42", "O(log n)"], ["top 10", "ZREVRANGE lb:2026-11 0 9 WITHSCORES", "O(log n + 10)"],
        ["my rank", "ZREVRANK lb:2026-11 user:42", "O(log n)"], ["players around me", "ZREVRANGE lb … rank−5 rank+5", "O(log n + 10)"], ["reset monthly", "new key per month + TTL", "O(1)"]]),
  SEQ("A game ends", ["Game server", "Score service", "Scores DB", "Redis ZSET", "Player"],
      [["Game server", "Score service", "match result (signed by server)", "", "Never trust the client: scores come from the game server, checked for impossible values."],
       ["Score service", "Scores DB", "INSERT score event (durable)", "", "The DB is the source of truth; Redis can be rebuilt from it."], ["Score service", "Redis ZSET", "ZINCRBY lb:2026-11 50 user:42"],
       ["Player", "Score service", "GET /leaderboard/me"], ["Score service", "Redis ZSET", "ZREVRANK + ZREVRANGE around me"], ["Score service", "Player", "rank 18,204 + neighbours", "r"]]),
  KEY("Ties: make the score unique by encoding time, e.g. score × 10¹⁰ + (MAX_TS − finish_time), so the earlier achiever ranks higher. Very large boards: shard by score range or keep exact top-N and approximate ranks (percentile buckets) for everyone else.", "Follow-up answers"))
